mapper.sql:
SELECT p.id, p.code, p.title, p.platform_type AS platformType, p.shop_id AS shopId, p.pricing, p.freight, e.visitors, e.pay_amt AS payAmount, e.pay_byrs AS payBuyers, e.cart_users AS cartUsers, DATE_FORMAT(e.snapshot_time, '%Y-%m-%d %H:%i') AS effectAt, IFNULL(s.source_count, 0) AS sourceCount, s.source_price AS sourcePrice, s.min_stock AS minStock, s.category_name AS categoryName, f.commission_rate AS commissionRate, f.payment_fee_rate AS paymentFeeRate, CASE WHEN p.pricing IS NULL OR p.pricing = 0 OR s.source_price IS NULL OR f.commission_rate IS NULL THEN NULL ELSE ROUND(p.pricing - s.source_price - p.pricing * (f.commission_rate + f.payment_fee_rate) / 100, 2) END AS margin, CASE WHEN p.pricing IS NULL OR p.pricing = 0 OR s.source_price IS NULL OR f.commission_rate IS NULL THEN NULL ELSE ROUND((p.pricing - s.source_price - p.pricing * (f.commission_rate + f.payment_fee_rate) / 100) / p.pricing * 100, 1) END AS marginRate FROM platform_product p LEFT JOIN (SELECT s1.item_id, s1.visitors, s1.pay_amt, s1.pay_byrs, s1.cart_users, s1.snapshot_time FROM sycm_item_effect_history s1 JOIN (SELECT item_id, MAX(id) AS max_id FROM sycm_item_effect_history GROUP BY item_id) s2 ON s2.max_id = s1.id) e ON e.item_id = p.code COLLATE utf8mb4_0900_ai_ci LEFT JOIN (SELECT br.product_id, COUNT(*) AS source_count, MIN(COALESCE(sk.min_price, sp.source_price)) AS source_price, MIN(COALESCE(sk.min_stock, 999999)) AS min_stock, MAX(sp.category_name) AS category_name FROM product_bind_relation br JOIN source_product sp ON sp.id = br.source_productId AND sp.is_deleted = 0 LEFT JOIN (SELECT source_product_id, MIN(CASE WHEN status = 1 THEN price END) AS min_price, MIN(CASE WHEN status = 1 THEN stock END) AS min_stock FROM source_sku WHERE is_deleted = 0 GROUP BY source_product_id) sk ON sk.source_product_id = sp.id WHERE br.is_deleted = 0 GROUP BY br.product_id) s ON s.product_id = p.id LEFT JOIN (SELECT platform_type, ROUND(AVG(commission_rate), 2) AS commission_rate, ROUND(AVG(payment_fee_rate), 3) AS payment_fee_rate FROM fee_benchmark WHERE is_deleted = 0 GROUP BY platform_type) f ON f.platform_type = p.platform_type
AND p.platform_type = #{platformType} AND p.shop_id = #{shopId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.code = #{keyword})
